<template>
  <div class="col-3 q-pl-md">
    <h4
      v-if="renderComponent === true"
      class="supplier-name-heading text-primary text-weight-bold q-mb-none"
    >
      {{ supplierName }}
    </h4>
  </div>
  <div class="col-6 wizard-wrapper">
    <SupplierWizard />
    <div :class="['action-wrapper', $q.dark.isActive && 'dark']">
      <q-btn
        v-if="visibleApproveAction()"
        color="negative"
        @click="rejectAction"
        >{{ $t('reject_supplier') }}</q-btn
      >
      <q-space />
      <q-btn @click="$router.push('/supplier/dashboard')" > 
        {{ $t('cancel') }}
      </q-btn>
      <q-btn color="primary" :disabled="isFileUploading" @click="save">{{
        $t('save')
      }}</q-btn>
      <q-btn
        v-if="visibleApproveAction()"
        color="primary"
        :disabled="isFileUploading"
        @click="confirmation = true"
        >{{ $t('request_release') }}</q-btn
      >
    </div>
    <ul class="error-list text-negative" v-if="supplierDetailsErrors">
      <li v-for="error in supplierDetailsErrors" :key="error">
        {{ error }}
      </li>
    </ul>
  </div>
  <div class="col-3">
    <SupplierDetailsSidebar />
  </div>
  <q-dialog v-model="dialogVisible">
    <q-card
      class="card"
      style="width: 50vw !important; max-width: 550px !important"
    >
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('reject') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>
      <form @submit.prevent.stop="submitRejection">
        <q-card-section class="row">
          <q-input
            v-model="msg"
            :label="$t('message')"
            outlined
            dense
            required
            type="textarea"
            class="col-12 card-padding"
          >
          </q-input>
        </q-card-section>
        <q-card-actions align="right">
          <f-btn :label="$t('cancel')" appearance="cancel" v-close-popup />
          <f-btn
            type="submit"
            class="q-mr-sm"
            :label="$t('send')"
          />
        </q-card-actions>
      </form>
    </q-card>
  </q-dialog>
  <ConfirmDialog
    v-model="confirmation"
    @confirm="submitApprove"
    :message="$t('are_you_sure_to_approve')"
  />
</template>
<script lang="ts">
import SupplierWizard from 'src/supplier/components/dynamic/SupplierWizard.vue';
import { defineComponent, ref, watch } from 'vue';
import { storeToRefs } from 'pinia';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
import SupplierDetailsSidebar from 'src/supplier/components/SupplierDetailsSidebar.vue';
import { useSupplierLayoutsStore, useUserStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions';
import { supplierDocumentType } from 'src/pages/Settings/SupplierLayouts/formBuilderConstants';
import { isManagementUser ,isTopLevelUserAdmin,isSupplierAdmin,isSupplierUser, getUserDetailFromkey, getUserDetails} from 'src/utils/UserDetails';
import { userApiService, documentPermissionsApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ArrayError } from '../utils';
import { useSettingStore } from 'src/store/main';
import { supplier_statuses } from 'src/constants';
import { useDashboardSupplierStore } from 'src/supplier/store/dashboard.store';
import { notify } from 'src/components/notifications/notify';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    SupplierWizard,
    SupplierDetailsSidebar,
    ConfirmDialog,
  },
  mounted() {
    this.init();
  },
  data() {
    return {
      //
    };
  },
  beforeUnmount() {
    this.formLayout = [];
    this.formConfigure = [];
    this.supplierDetailsErrors = [];
    this.supplierUploadStatus = {};
    this.renderComponent = false;
    this.layout_type = '';
    this.last_updated_at = '';
    this.isFromClickSave = false;
  },
  computed: {
    isEditable: function () {
      const editable =
        this.$route.params.id === 'supplier_as_org_id' ||
        this.status === 'rejected' ||
        this.status === 'pending_approval' ||
        this.status === 'pending_ap_approval';
      return editable;
    },
    isFileUploading: function () {
      let is_uploading = false;
      for (const key in this.supplierUploadStatus) {
        if (this.supplierUploadStatus[key].status === 'loading')
          is_uploading = true;
      }
      return is_uploading;
    },
    supplierName: function (): any {
      let name = '';
      for (const key in this.formConfigure) {
        if (this.formConfigure[key]?.supplier_name) {
          name = this.formConfigure[key]?.supplier_name;
        }
      }
      return name;
    },
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const {
      loading,
      formLayout,
      status,
      supplierDetailsErrors,
      formConfigure,
      renderComponent,
      supplierUploadStatus,
      last_updated_at,
      layout_type,
      isFromClickSave,
      requester_id,
      assigned_user_id,
    } = storeToRefs(supplier_layouts_store);
    const {
      fetchOrgSupplier,
      getSuppierLayoutByID,
      populateForm,
      approve,
      reject,
      validateAllForm,
      updateSupplier,
      sendForApproval,
    } = supplier_layouts_store;

    const setting_store = useSettingStore();
    const { user_settings } = storeToRefs(setting_store);

    const dashboard_supplier_store = useDashboardSupplierStore();
    const { supplierStatusList } = storeToRefs(dashboard_supplier_store);

    const userGroups = ref<string[]>([]);

    return {
      loading,
      formLayout,
      formConfigure,
      fetchOrgSupplier,
      dialogVisible: ref(false),
      confirmation: ref(false),
      status,
      isAdmin: ref(false),
      getSuppierLayoutByID,
      populateForm,
      approve,
      reject,
      validateAllForm,
      updateSupplier,
      sendForApproval,
      msg: ref(''),
      supplierDetailsErrors,
      renderComponent,
      supplierUploadStatus,
      last_updated_at,
      layout_type,
      isFromClickSave,
      user_settings,
      supplier_statuses,
      supplierStatusList,
      userGroups,
      requester_id,
      assigned_user_id,
    };
  },
  methods: {
    async init() {
      const user_store = useUserStore();
      const parent_ord_id = user_store.getParentOrgId();
      this.loading = true;
      this.renderComponent = false;
      this.formLayout = [];
      let layout_type = supplierDocumentType.SUPPLIER_USER;
      if (isManagementUser() || isTopLevelUserAdmin() || isSupplierAdmin()) {
        layout_type = supplierDocumentType.SUPPLIER_MANAGEMENT;
      } else if (isSupplierUser()) {
        layout_type = supplierDocumentType.SUPPLIER_USER;
      }
      try {
        await this.getSuppierLayoutByID(layout_type, parent_ord_id);
        await this.getDataListing();
      } catch (err: any) {
        logError(err);
      } finally {
        this.renderComponent = true;
        this.loading = false;
      }
      this.supplierStatusList = JSON.parse(
        this.user_settings[this.supplier_statuses],
      );
      await this.fetchUserGroups();
    },
    async fetchUserGroups() {
      try {
        // getUserAcls() (/access_controls/get_doc_type_permissions) only
        // returns groups that have doc-type permissions configured — not the
        // groups the user is a member of. Use getUserGroups() instead.
        const response = await documentPermissionsApiService.getUserGroups();
        if (Array.isArray(response)) {
          this.userGroups = response.map((group: { id: string }) => group.id);
        }
      } catch (e: any) {
        logError(e);
      }
    },
    async getDataListing() {
      if (this.$route.params.oldId && this.$route.params.id) {
        await this.fetchOrgSupplier(
          this.$route.params.oldId as string,
          this.$route.params.id as string,
        );
      }
    },
    async save() {
      this.loading = true;
      try {
        await this.validateAllForm();
        await this.updateSupplier(this.$route.params.id)
          .then(async (res) => {
            await this.fetchOrgSupplier(
              this.$route.params.oldId as string,
              this.$route.params.id as string,
            );
            notify.success('Supplier is saved successfully');
          })
          .catch((e: any) => {
            const message = ApiExceptions.getErrorMessage(e);
            notify.error(message);
          });
      } catch (error: any) {
        const message = ApiExceptions.getErrorMessage(error);
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
    visibleApproveAction() {
      this.isAdmin = Boolean(
        JSON.parse(getUserDetailFromkey('is_organisation_admin')),
      );

      // Find the config for the current status (only relevant if it's an
      // approval status). If not for-approval or no config, no approve action.
      const currentStatusConfig = (this.supplierStatusList as any[]).find(
        (item: any) =>
          item.is_for_approval === true && item.value === this.status,
      );
      if (!currentStatusConfig) {
        return false;
      }

      const currentUserId = String(getUserDetailFromkey('id') ?? '');
      const statusUserGroups: string[] = currentStatusConfig.user_groups || [];

      // Each rule is independently OR'd — if ANY enabled toggle's condition
      // matches the current user, the approve button is shown.
      const adminCanApprove = Boolean(
        currentStatusConfig.admin_can_approve && this.isAdmin,
      );

      const referrerCanApprove = Boolean(
        currentStatusConfig.referer_can_approve &&
          this.requester_id &&
          String(this.requester_id) === currentUserId,
      );

      const assigneeCanApprove = Boolean(
        currentStatusConfig.assignee_can_approve &&
          this.assigned_user_id &&
          String(this.assigned_user_id) === currentUserId,
      );

      const groupCanApprove =
        statusUserGroups.length > 0 &&
        Array.isArray(this.userGroups) &&
        this.userGroups.length > 0 &&
        statusUserGroups.some((groupId: string) =>
          this.userGroups.includes(groupId),
        );

      return (
        adminCanApprove ||
        referrerCanApprove ||
        assigneeCanApprove ||
        groupCanApprove
      );
    },
    rejectAction() {
      this.dialogVisible = true;
    },
    async submitRejection() {
      this.loading = true;

      const data = {
        supplier_as_org_id: this.$route.params.id,
        supplier_lookup_record_id: this.$route.params.oldId,
        message: this.msg,
      };
      try {
        await this.reject(data);
        notify.success(this.$t('rejected_successfully'));
        await this.fetchOrgSupplier(
          this.$route.params.oldId as string,
          this.$route.params.id as string,
        );
      } catch (error) {
        const message = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(message);
      } finally {
        this.msg = '';
        this.loading = false;
        this.dialogVisible = false;
      }
    },
    async submitApprove() {
      this.loading = true;
      const data = {
        supplier_as_org_id: this.$route.params.id,
        supplier_lookup_record_id: this.$route.params.oldId,
        status: this.status,
      };
      try {
        const formIsValid = await this.validateAllForm();
        if (!formIsValid) {
          notify.error(
            this.$t('form_validated_failed'),
          );
          return;
        }

        await this.updateSupplier(this.$route.params.id).catch((e: any) => {
          const message = ApiExceptions.getErrorMessage(e);
          notify.error(message);
        });
        await this.approve(data);
        this.supplierDetailsErrors = [];
        notify.success(this.$t('approved_successfully'));
        // reload neccessary data once we approved
        await this.init();
      } catch (error) {
        if (error instanceof ArrayError) {
          this.supplierDetailsErrors = error.messages;
        } else {
          const message = ApiExceptions.getErrorMessage(error as dynamicObj);
          notify.error(message);
        }
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>
<style scoped lang="scss">
.error-list {
  margin: 0;
  padding-left: 12px !important;
  line-height: 1.2;
  list-style-position: inside;
}
</style>
